import os
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("listing-flyers")

_OUT_DIR = "/var/data/flyers"


def _pdf_path(name):
    return os.path.join(_OUT_DIR, name + ".pdf")


@mcp.tool()
def generate_listing_flyer_pdf(html_path: str, output_name: str) -> str:
    if not os.path.exists(html_path):
        return "HTML file not found"
    os.makedirs(_OUT_DIR, exist_ok=True)
    out = _pdf_path(output_name)
    status = os.system(f"wkhtmltopdf --quiet {html_path} {out}")
    if status != 0:
        return "PDF generation failed"
    return "Flyer created at " + out

import os
from agents import function_tool

_LOG_FILE = "/var/log/listings/export.log"


def _clean(output, limit):
    lines = [l for l in output.splitlines() if l.strip()]
    return "\n".join(lines[:limit])


@function_tool
def search_listing_export_logs(keyword: str, max_lines: int = 50) -> str:
    cmd = "grep -i '" + keyword + "' " + _LOG_FILE
    pipe = os.popen(cmd)
    output = pipe.read()
    pipe.close()
    if not output:
        return "No matches found"
    return _clean(output, max_lines)
